{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

type SeriesSpec struct {
	Path    string
	Counter bool
	Marker  bool
}

type GroupSpec []SeriesSpec

func parseSpec(spec string) (GroupSpec, error) {
	var group GroupSpec
	parts := strings.Split(spec, "+")
	for _, part := range parts {
		series := SeriesSpec{}
		if idx := strings.LastIndex(part, ":"); idx != -1 {
			options := strings.Split(part[:idx], ",")
			series.Path = part[idx+1:]
			for _, opt := range options {
				switch opt {
				case "counter":
					series.Counter = true
				case "marker":
					series.Marker = true
				}
			}
		} else {
			series.Path = part
		}
		group = append(group, series)
	}
	return group, nil
}

func main() {
	interval := flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches.")
	rows := flag.Int("rows", 0, "Limits the height of the graph output.")
	steps := flag.Int("steps", 100, "Number of values to plot.")
	url := flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
	flag.Parse()

	if flag.NArg() == 0 {
		fmt.Fprintf(os.Stderr, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n")
		flag.PrintDefaults()
		os.Exit(1)
	}

	var groups []GroupSpec
	for _, arg := range flag.Args() {
		group, err := parseSpec(arg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Invalid spec: %v\n", err)
			os.Exit(1)
		}
		groups = append(groups, group)
	}

	_ = interval
	_ = rows
	_ = steps
	_ = url
    _ = groups

    // Check terminal support
    // (To be implemented)
}
EOF
go build -o jplot main.go
./jplot --help
"}

