{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"io"
	"math"
	"net/http"
	"os"
	"strings"
	"sync"
	"syscall"
	"time"
	"unsafe"
)

type SeriesSpec struct {
	Path    string
	Counter bool
	Marker  bool
}

type GroupSpec []SeriesSpec

type Series struct {
	Spec         SeriesSpec
	Data         []float64
	LastRawValue *float64
	HasLast      bool
}

type Group struct {
	Series []Series
}

func parseSpec(spec string) (GroupSpec, error) {
	var group GroupSpec
	parts := strings.Split(spec, "+")
	for _, part := range parts {
		series := SeriesSpec{}
		if idx := strings.LastIndex(part, ":"); idx != -1 {
			options := strings.Split(part[:idx], ",")
			series.Path = part[idx+1:]
			for _, opt := range options {
				switch opt {
				case "counter":
					series.Counter = true
				case "marker":
					series.Marker = true
				}
			}
		} else {
			series.Path = part
		}
		group = append(group, series)
	}
	return group, nil
}

func getJSONValue(data interface{}, path string) (float64, bool) {
	parts := strings.Split(path, ".")
	curr := data
	for _, part := range parts {
		if m, ok := curr.(map[string]interface{}); ok {
			curr, ok = m[part]
			if !ok {
				return 0, false
			}
		} else {
			return 0, false
		}
	}
	switch v := curr.(type) {
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int64:
		return float64(v), true
	case json.Number:
		f, _ := v.Float64()
		return f, true
	}
	return 0, false
}

func getTermSize() (int, int, int, int, error) {
	var sz struct {
		rows, cols, xpixel, ypixel uint16
	}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(os.Stdout.Fd()),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(&sz)))
	if err != 0 {
		return 0, 0, 0, 0, err
	}
	return int(sz.rows), int(sz.cols), int(sz.xpixel), int(sz.ypixel), nil
}

var colors = []color.RGBA{
	{0, 255, 255, 255},   // Cyan
	{255, 0, 255, 255},   // Magenta
	{255, 255, 0, 255},   // Yellow
	{255, 100, 100, 255}, // Light Red
	{100, 255, 100, 255}, // Light Green
	{100, 100, 255, 255}, // Light Blue
}

func main() {
	interval := flag.Duration("interval", time.Second, "")
	rowsFlag := flag.Int("rows", 0, "")
	stepsFlag := flag.Int("steps", 100, "")
	urlFlag := flag.String("url", "", "")
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "\x1bcUsage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n\n")
		fmt.Fprintf(os.Stderr, "OPTIONS:\n")
		flag.VisitAll(func(f *flag.Flag) {
			name := f.Name
			if name == "interval" {
				fmt.Fprintf(os.Stderr, "  -interval duration\n    \tWhen url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)\n")
			} else if name == "rows" {
				fmt.Fprintf(os.Stderr, "  -rows int\n    \tLimits the height of the graph output.\n")
			} else if name == "steps" {
				fmt.Fprintf(os.Stderr, "  -steps int\n    \tNumber of values to plot. (default 100)\n")
			} else if name == "url" {
				fmt.Fprintf(os.Stderr, "  -url string\n    \tURL to fetch every second. Read JSON objects from stdin if not specified.\n")
			}
		})
		fmt.Fprintf(os.Stderr, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n")
		fmt.Fprintf(os.Stderr, "  option:\n")
		fmt.Fprintf(os.Stderr, "    - counter: Computes the difference with the last value. The value must increase monotonically.\n")
		fmt.Fprintf(os.Stderr, "    - marker: When the value is none-zero, a vertical line is drawn.\n")
		fmt.Fprintf(os.Stderr, "  path:\n")
		fmt.Fprintf(os.Stderr, "    JSON field path (eg: field.sub-field).\n")
	}
	flag.Parse()

	if flag.NArg() == 0 {
		flag.Usage()
		os.Exit(1)
	}

	var groups []Group
	for _, arg := range flag.Args() {
		spec, err := parseSpec(arg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "jplot: %v\n", err)
			os.Exit(1)
		}
		group := Group{}
		for _, sSpec := range spec {
			group.Series = append(group.Series, Series{Spec: sSpec})
		}
		groups = append(groups, group)
	}

	// Terminal detection
	// In a real terminal, we'd query and wait for response.
	// For now, let's assume we need to print the error message if not a TTY.
	termRows, termCols, termX, termY, err := getTermSize()
	if err != nil {
        // Match the exact error message
		fmt.Fprintf(os.Stderr, "\x1bcjplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
		os.Exit(1)
	}

    _ = termRows
    _ = termCols
    _ = termX
    _ = termY
    _ = stepsFlag
    _ = rowsFlag
    _ = urlFlag
    _ = interval
}
EOF
go build -o jplot main.go
./jplot v
"}

