func (p *plotter) process(data interface{}) {
	for i := range p.groups {
		for j := range p.groups[i].Series {
			s := &p.groups[i].Series[j]
			val, ok := getJSONValue(data, s.Spec.Path)
			if !ok {
				val = 0
			}
			plotVal := val
			if s.Spec.Counter {
				if s.HasLast {
					plotVal = val - *s.LastRawValue
				} else {
					plotVal = 0
				}
				s.HasLast = true
				last := val
				s.LastRawValue = &last
			}
			s.Data = append(s.Data, plotVal)
			if len(s.Data) > p.steps {
				s.Data = s.Data[1:]
			}
		}
	}
}

func drawLine(img draw.Image, x0, y0, x1, y1 int, c color.Color) {
	dx := int(math.Abs(float64(x1 - x0)))
	dy := int(math.Abs(float64(y1 - y0)))
	sx, sy := -1, -1
	if x0 < x1 { sx = 1 }
	if y0 < y1 { sy = 1 }
	err := dx - dy
	for {
		img.Set(x0, y0, c)
		if x0 == x1 && y0 == y1 { break }
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
