	_, _, termX, termY, err := getTermSize()
	if err != nil {
		return
	}
	if termX == 0 { termX = 800 }
	if termY == 0 { termY = 600 }

	width := termX
	height := termY
	if p.rows > 0 {
		// Estimate height from rows
