                        drawLine(img, x, yOffset, x, yOffset + graphHeight, c)
                    }
                }
            } else {
                // Draw lines
                for i := 1; i < len(s.Data); i++ {
                    x0 := int(float64(i-1) * float64(width) / float64(p.steps-1))
                    x1 := int(float64(i) * float64(width) / float64(p.steps-1))
                    y0 := yOffset + graphHeight - int((s.Data[i-1]-minVal)/(maxVal-minVal)*float64(graphHeight-10)) - 5
                    y1 := yOffset + graphHeight - int((s.Data[i]-minVal)/(maxVal-minVal)*float64(graphHeight-10)) - 5
                    drawLine(img, x0, y0, x1, y1, c)
                }
            }
        }
    }

	// Output image
    // For now, let's use iTerm2 protocol
	var buf bytes.Buffer
	png.Encode(&buf, img)
	fmt.Printf("\033]1337;File=inline=1;width=%dpx;height=%dpx;size=%d:%s\a\r", width, height, buf.Len(), base64.StdEncoding.EncodeToString(buf.Bytes()))
}

