package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"math"
	"net/http"
	"os"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

type SeriesSpec struct {
	Path    string
	Counter bool
	Marker  bool
}

type Series struct {
	Spec         SeriesSpec
	Data         []float64
	LastRawValue float64
	HasLast      bool
}

type Group struct {
	Series []Series
}

func parseSpec(spec string) ([]SeriesSpec, error) {
	var seriesSpecs []SeriesSpec
	parts := strings.Split(spec, "+")
	for _, part := range parts {
		s := SeriesSpec{}
		if idx := strings.LastIndex(part, ":"); idx != -1 {
			options := strings.Split(part[:idx], ",")
			s.Path = part[idx+1:]
			for _, opt := range options {
				switch opt {
				case "counter":
					s.Counter = true
				case "marker":
					s.Marker = true
				}
			}
		} else {
			s.Path = part
		}
		seriesSpecs = append(seriesSpecs, s)
	}
	return seriesSpecs, nil
}

func getJSONValue(data interface{}, path string) (float64, bool) {
	parts := strings.Split(path, ".")
	curr := data
	for _, part := range parts {
		if m, ok := curr.(map[string]interface{}); ok {
			var ok2 bool
			curr, ok2 = m[part]
			if !ok2 {
				return 0, false
			}
		} else {
			return 0, false
		}
	}
	switch v := curr.(type) {
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int64:
		return float64(v), true
	case json.Number:
		f, _ := v.Float64()
		return f, true
	}
	return 0, false
}

func getTermSize() (int, int, int, int, error) {
	var sz struct {
		rows, cols, xpixel, ypixel uint16
	}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(os.Stdout.Fd()),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(&sz)))
	if err != 0 {
		return 0, 0, 0, 0, err
	}
	return int(sz.rows), int(sz.cols), int(sz.xpixel), int(sz.ypixel), nil
}

var palette = []color.RGBA{
	{0, 255, 255, 255},   // Cyan
	{255, 0, 255, 255},   // Magenta
	{255, 255, 0, 255},   // Yellow
	{100, 255, 100, 255}, // Green
	{255, 100, 100, 255}, // Red
	{100, 100, 255, 255}, // Blue
}

type plotter struct {
	groups   []Group
	steps    int
	rows     int
	interval time.Duration
	url      string
	client   *http.Client
}

func (p *plotter) process(data interface{}) {
	for i := range p.groups {
		for j := range p.groups[i].Series {
			s := &p.groups[i].Series[j]
			val, _ := getJSONValue(data, s.Spec.Path)
			plotVal := val
			if s.Spec.Counter {
				if s.HasLast {
					plotVal = val - s.LastRawValue
				} else {
					plotVal = 0
				}
				s.HasLast = true
				s.LastRawValue = val
			}
			s.Data = append(s.Data, plotVal)
			if len(s.Data) > p.steps {
				s.Data = s.Data[1:]
			}
		}
	}
}

func drawLine(img draw.Image, x0, y0, x1, y1 int, c color.Color) {
	dx := int(math.Abs(float64(x1 - x0)))
	dy := int(math.Abs(float64(y1 - y0)))
	sx, sy := -1, -1
	if x0 < x1 { sx = 1 }
	if y0 < y1 { sy = 1 }
	err := dx - dy
	for {
		img.Set(x0, y0, c)
		if x0 == x1 && y0 == y1 { break }
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
}

func (p *plotter) render() {
	termR, _, termX, termY, err := getTermSize()
	if err != nil {
		return
	}
	if termX == 0 { termX = 800 }
	if termY == 0 { termY = 600 }

	width := termX
	height := termY
	if p.rows > 0 {
		if termR > 0 {
			height = (termY / termR) * p.rows
		} else {
			height = 20 * p.rows
		}
	}

	img := image.NewRGBA(image.Rect(0, 0, width, height))

    if len(p.groups) == 0 { return }
    graphHeight := height / len(p.groups)
    for gIdx, group := range p.groups {
        yOffset := gIdx * graphHeight

        minVal, maxVal := 0.0, 0.0
        first := true
        for _, s := range group.Series {
            if s.Spec.Marker { continue }
            for _, v := range s.Data {
                if first {
                    minVal, maxVal = v, v
                    first = false
                } else {
                    if v < minVal { minVal = v }
                    if v > maxVal { maxVal = v }
                }
            }
        }
        if maxVal <= minVal {
            maxVal = minVal + 1
        }

        for sIdx, s := range group.Series {
            c := palette[sIdx%len(palette)]
            if s.Spec.Marker {
                for i, v := range s.Data {
                    if v != 0 {
                        x := int(float64(i) * float64(width) / float64(p.steps-1))
                        drawLine(img, x, yOffset, x, yOffset + graphHeight, c)
                    }
                }
            } else {
                for i := 1; i < len(s.Data); i++ {
                    x0 := int(float64(i-1) * float64(width) / float64(p.steps-1))
                    x1 := int(float64(i) * float64(width) / float64(p.steps-1))
                    y0 := yOffset + graphHeight - int((s.Data[i-1]-minVal)/(maxVal-minVal)*float64(graphHeight-10)) - 5
                    y1 := yOffset + graphHeight - int((s.Data[i]-minVal)/(maxVal-minVal)*float64(graphHeight-10)) - 5
                    if y0 < yOffset { y0 = yOffset }
                    if y0 >= yOffset + graphHeight { y0 = yOffset + graphHeight - 1 }
                    if y1 < yOffset { y1 = yOffset }
                    if y1 >= yOffset + graphHeight { y1 = yOffset + graphHeight - 1 }
                    drawLine(img, x0, y0, x1, y1, c)
                }
            }
        }
    }

	var buf bytes.Buffer
	png.Encode(&buf, img)

    fmt.Printf("\033[u")
    fmt.Printf("\033]1337;File=inline=1;width=%dpx;height=%dpx;size=%d:%s\a\r", width, height, buf.Len(), base64.StdEncoding.EncodeToString(buf.Bytes()))
    b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
    for i := 0; i < len(b64); i += 4096 {
        chunk := b64[i:]
        m := 1
        if len(chunk) <= 4096 {
            m = 0
        } else {
            chunk = b64[i : i+4096]
        }
        fmt.Printf("\033_Gf=100,a=T,m=%d;%s\033\\", m, chunk)
    }
}

func (p *plotter) initTerm() {
    termR, _, _, _, err := getTermSize()
    if err != nil { return }
    fmt.Printf("\033[?25l")
    h := p.rows
    if h == 0 { h = termR }
    for i := 0; i < h; i++ {
        fmt.Println()
    }
    fmt.Printf("\033[%dA", h)
    fmt.Printf("\033[s")
}

